// The interactive technique map: one diagram per RAG architecture. Each box explains itself (what it is, how it works,
// why it exists, how to change it), and links to the day that teaches it. Used by components/InteractiveMap.tsx.
// Layout is a 5-column grid (c 0..4) by row (r): the component turns that into SVG coordinates.

export type Kind = "data" | "process" | "model" | "store" | "decision" | "guard" | "output";

export type DNode = {
  id: string;
  label: string; // short: fits a 156px box
  sub?: string; // one short line under the label
  c: number;
  r: number;
  kind: Kind;
  what: string;
  how: string;
  why: string;
  tune: string[]; // how to modify or update it
  watch?: string; // the common way it goes wrong
  days?: number[];
};

export type DEdge = { from: string; to: string; label?: string; dashed?: boolean; route?: "above" | "below"; lift?: number };

export type Diagram = {
  id: string;
  name: string;
  blurb: string; // one sentence for the select and the overview
  when: string; // when to reach for it
  tradeoff: string; // what it costs
  rows: number;
  days: number[]; // build it
  projects: string[]; // project slugs
  nodes: DNode[];
  edges: DEdge[];
};

export const KINDS: Record<Kind, { label: string; color: string }> = {
  data: { label: "Data", color: "var(--muted)" },
  process: { label: "Step", color: "var(--accent)" },
  model: { label: "Model", color: "var(--ai)" },
  store: { label: "Store / index", color: "var(--info)" },
  decision: { label: "Decision", color: "var(--warm)" },
  guard: { label: "Safety / quality gate", color: "var(--hot)" },
  output: { label: "Result", color: "var(--good)" },
};

